-- Serves WHERE tenant_id = ? AND status = ?  and  WHERE tenant_id = ?
CREATE INDEX idx_orders_tenant_status ON orders (tenant_id, status);

-- Uses the index (leftmost prefix present):
EXPLAIN SELECT * FROM orders WHERE tenant_id = 42 AND status = 'OPEN';
EXPLAIN SELECT * FROM orders WHERE tenant_id = 42;

-- Does NOT use the composite index efficiently (status is not the leftmost column):
EXPLAIN SELECT * FROM orders WHERE status = 'OPEN';

-- Fix if that pattern is hot:
CREATE INDEX idx_orders_status ON orders (status);

BEGIN TRANSACTION;

UPDATE accounts
SET balance = balance - 100
WHERE account_id = 'A' AND balance >= 100;  -- guard against overdraft

IF @@ROWCOUNT <> 1
BEGIN
  ROLLBACK TRANSACTION;   -- insufficient funds or account missing
  THROW 50001, 'Transfer failed: insufficient funds', 1;
END;

UPDATE accounts
SET balance = balance + 100
WHERE account_id = 'B';

IF @@ROWCOUNT <> 1
BEGIN
  ROLLBACK TRANSACTION;   -- destination account missing
  THROW 50002, 'Transfer failed: destination not found', 1;
END;

COMMIT TRANSACTION;

-- BEST: atomic increment avoids the read-modify-write race entirely
UPDATE counters
SET value = value + 1
WHERE name = 'page_views';

-- If you must read first, lock the row pessimistically:
BEGIN;
SELECT value FROM counters WHERE name = 'page_views' FOR UPDATE; -- row write-lock
-- ... compute new value in app ...
UPDATE counters SET value = value + 1 WHERE name = 'page_views';
COMMIT;

-- Or raise the isolation level for the session:
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

-- DEADLOCK-PRONE: the two sessions lock accounts in opposite orders
-- Session 1:                       Session 2:
BEGIN;                            -- BEGIN;
UPDATE accounts SET balance=balance-50 WHERE id=1;  -- UPDATE ... WHERE id=2;
UPDATE accounts SET balance=balance+50 WHERE id=2;  -- UPDATE ... WHERE id=1;  <-- cycle!
COMMIT;

-- SAFE: transfer 50 from :src to :dst, but always lock rows in a
-- consistent order (ascending id) so no cycle can form. A single
-- statement that touches both rows lets the engine lock them in
-- index (id) order; the CASE keeps the debit/credit on the right rows.
BEGIN;
UPDATE accounts
SET balance = CASE
                WHEN id = :src THEN balance - 50
                WHEN id = :dst THEN balance + 50
              END
WHERE id IN (:src, :dst);
COMMIT;

-- NON-SARGable: function on the column defeats the index -> full scan
SELECT * FROM orders
WHERE YEAR(created_at) = 2025;

-- SARGable rewrite: bare column vs constant range -> index range scan
SELECT * FROM orders
WHERE created_at >= '2025-01-01'
  AND created_at <  '2026-01-01';

-- Alternative: an index on the expression itself (PostgreSQL)
CREATE INDEX idx_orders_year ON orders ((EXTRACT(YEAR FROM created_at)));
